mapper.select:
SELECT seq, writerid AS writerId, title, content, readcount, wdate, ispinned
FROM board
WHERE seq = #{seq}

mapper.update:
UPDATE board
SET readcount = readcount + 1
WHERE seq = #{seq}

UPDATE board
SET title = #{title},
    content = #{content},
    ispinned = #{ispinned}
WHERE seq = #{seq} AND writerid = #{writerId}

UPDATE comments
SET content = #{content}
WHERE seq = #{seq} AND writerid = #{writerId}

UPDATE board 
SET title = #{title}, 
    content = #{content},
    ispinned = #{ispinned}
WHERE seq = #{seq}
